#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long k;
    cin >> n >> k;

    const long long MOD = 1000000007;
    long long same = 0, diff = k % MOD;
    for (long long i = 1; i < n; i++) {
        long long newSame = diff;
        long long newDiff = (same + diff) % MOD * ((k - 1) % MOD) % MOD;
        same = newSame;
        diff = newDiff;
    }
    cout << (same + diff) % MOD << "\n";

    return 0;
}

